@@ -130,7 +142,7 @@ static int edac_probe(struct platform_device *pdev)
 	struct mem_ctl_info *mci;
 	struct device *dev = &pdev->dev;
 	void __iomem *vbase;
-	u32 mc_per_node;
+	u32 mc_per_node, valid_cs_bits;
